// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address adminActor, address newOwner) public {
        vm.assume(adminActor != address(0));
        vm.assume(newOwner != address(0));

        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && (c.owner() == newOwner));
    }
}
